-- AAGMAN content/media persistence foundation.
-- Safe to rerun: existing catalogue rows are preserved and only missing slugs are seeded.
alter table public.destinations
  alter column gallery type jsonb
  using case when gallery is null then '[]'::jsonb else to_jsonb(gallery) end;
alter table public.destinations alter column gallery set default '[]'::jsonb;

alter table public.festivals
  add column if not exists gallery jsonb not null default '[]'::jsonb;

alter table public.videos
  add column if not exists destination_slug text,
  add column if not exists festival_slug text;

create index if not exists videos_destination_slug_idx on public.videos (destination_slug);
create index if not exists videos_festival_slug_idx on public.videos (festival_slug);
create index if not exists videos_youtube_id_idx on public.videos (youtube_id);

-- Seed all 41 destinations from the checked-in catalogue. UUIDs are deterministic.
insert into public.destinations
  (id, name, slug, category, district, region, marathi_name, image_url, hero_image,
   description, gallery, highlights, status, is_published)
select
  (substr(md5('aagman-destination:' || v.slug),1,8) || '-' ||
   substr(md5('aagman-destination:' || v.slug),9,4) || '-' ||
   substr(md5('aagman-destination:' || v.slug),13,4) || '-' ||
   substr(md5('aagman-destination:' || v.slug),17,4) || '-' ||
   substr(md5('aagman-destination:' || v.slug),21,12))::uuid,
  v.name, v.slug, v.category, v.district, v.region, v.marathi_name,
  v.image_url, v.image_url, v.description, '[]'::jsonb, '[]'::jsonb,
  'published'::content_status, true
from (values
('raigad-fort', 'Raigad Fort', 'forts', 'Raigad', 'Konkan', 'किल्ले रायगड', 'https://images.unsplash.com/photo-1627894483216-2138af692e32?auto=format&fit=crop&w=1600&q=80', 'The sovereign capital of the Maratha Empire, where Chhatrapati Shivaji Maharaj was crowned in 1674.'),
('sinhagad-fort', 'Sinhagad Fort', 'forts', 'Pune', 'Western Maharashtra', 'सिंहगड किल्ला', 'https://images.unsplash.com/photo-1609137144813-7d9921338f24?auto=format&fit=crop&w=1600&q=80', 'The legendary ''Lion Fort'' captured by Tanaji Malusare in the daring Battle of Sinhagad in 1670.'),
('pratapgad-fort', 'Pratapgad Fort', 'forts', 'Satara', 'Western Maharashtra', 'प्रतापगड किल्ला', 'https://images.unsplash.com/photo-1589308078059-be1415eab4c3?auto=format&fit=crop&w=1600&q=80', 'The historic fortress where Shivaji Maharaj outmaneuvered Bijapuri General Afzal Khan in 1659.'),
('murud-janjira-fort', 'Murud-Janjira Sea Fortress', 'forts', 'Raigad', 'Konkan', 'मुरुड जंजिरा जलदुर्ग', 'https://images.unsplash.com/photo-1544644181-1484b3fdfc62?auto=format&fit=crop&w=1600&q=80', 'An invincible marine island fortress with 19 rounded bastions that remained undefeated for centuries.'),
('shivneri-fort', 'Shivneri Fort', 'forts', 'Pune', 'Western Maharashtra', 'किल्ले शिवनेरी', 'https://images.unsplash.com/photo-1626014303757-6466299b39be?auto=format&fit=crop&w=1600&q=80', 'The sacred birthplace of Chhatrapati Shivaji Maharaj (born 19 February 1630) surrounded by ancient Buddhist caves.'),
('rajgad-fort', 'Rajgad Fort', 'forts', 'Pune', 'Western Maharashtra', 'किल्ले राजगड', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1600&q=80', 'The ''King of Forts'' that served as the capital of the Maratha Empire for 26 crucial years.'),
('torna-fort', 'Torna Fort (Prachandagad)', 'forts', 'Pune', 'Western Maharashtra', 'किल्ले तोरणा (प्रचंडगड)', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1600&q=80', 'The very first fort captured by 16-year-old Shivaji Maharaj in 1646, sounding the bugle of Swarajya.'),
