-- Seed all 15 festivals. Their UUIDs are also deterministic.
insert into public.festivals
  (id, name, slug, marathi_name, dates, location, image, description,
   significance, gallery, highlights, status)
select
  (substr(md5('aagman-festival:' || v.slug),1,8) || '-' ||
   substr(md5('aagman-festival:' || v.slug),9,4) || '-' ||
   substr(md5('aagman-festival:' || v.slug),13,4) || '-' ||
   substr(md5('aagman-festival:' || v.slug),17,4) || '-' ||
   substr(md5('aagman-festival:' || v.slug),21,12))::uuid,
  v.name, v.slug, v.marathi_name, v.dates, v.location, v.image, v.description,
  v.significance, '[]'::jsonb, '[]'::jsonb, 'published'::content_status
from (values
('ganeshotsav', 'Ganeshotsav (Ganesh Chaturthi)', 'गणेशोत्सव', 'August – September (Bhadrapada Shukla Chaturthi)', 'Statewide (Celebrated with grand fervor in Pune & Mumbai)', 'https://images.unsplash.com/photo-1598387993441-a364f854c3e1?auto=format&fit=crop&w=800&q=80', 'Maharashtra''s grand 10-day cultural festival, popularised as a public celebration by Lokmanya Tilak in the 1890s. Features magnificent pandals, traditional Dhol-Tasha pathaks, cultural stage performances, and grand immersion (visarjan) processions.', 'Celebrates Lord Ganesha, the remover of obstacles. Fosters unity, performing arts, and traditional Maharashtrian hospitality.'),
('shiv-jayanti', 'Chhatrapati Shivaji Maharaj Jayanti', 'शिवजयंती', '19 February', 'Shivneri Fort, Raigad Fort & Statewide', 'https://images.unsplash.com/photo-1576487248805-cf45f6bcc67f?auto=format&fit=crop&w=800&q=80', 'The birth anniversary of the founder of the Maratha Empire, Chhatrapati Shivaji Maharaj. Commemorated with traditional torch processions (mashaal morcha), Powada folk ballads, traditional lezim dances, and state honors at his birthplace on Shivneri.', 'Honors the ideals of Swarajya, ethical governance, and the indomitable Maratha spirit.'),
('pandharpur-wari', 'Pandharpur Ashadhi Wari', 'पंढरपूर आषाढी वारी', 'June – July (Ashadha month)', 'Alandi / Dehu to Pandharpur (250 km walking pilgrimage)', 'https://images.unsplash.com/photo-1561361513-2d000a50f0dc?auto=format&fit=crop&w=800&q=80', 'An 800-year-old walking pilgrimage where over a million devout Warkaris accompany the sacred padukas (footprints) of Sant Dnyaneshwar and Sant Tukaram on foot over 21 days to the Vitthal Temple in Pandharpur, chanting ''Gyanba Tukaram''.', 'A living pilgrimage tradition centred on devotion, equality, communal harmony, and spiritual discipline.'),
('ellora-ajanta-festival', 'Ellora-Ajanta International Music & Dance Festival', 'वेरूळ-अजिंठा आंतरराष्ट्रीय महोत्सव', 'Dates vary by edition; confirm with the current organiser announcement', 'Soneri Mahal / Ellora Caves, Chhatrapati Sambhajinagar', 'https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=800&q=80', 'A prestigious 3-day classical music and dance festival with the ancient rock-cut monolithic Kailasa temple and Soneri Mahal as magnificent backdrops. Features India''s greatest classical vocalists, sitarists, Kathak and Odissi dancers.', 'Brings alive ancient Indian heritage through living classical performing arts.'),
('gudhi-padwa', 'Gudhi Padwa (Marathi New Year)', 'गुढीपाडवा', 'March – April (Chaitra Shukla Pratipada)', 'Statewide (Grand Shobha Yatras in Girgaon, Thane, Dombivli, Pune)', 'https://images.unsplash.com/photo-1608889825205-eebdb9fc5806?auto=format&fit=crop&w=800&q=80', 'The traditional New Year day for the people of Maharashtra. Families hoist an auspicious silk-draped ''Gudhi'' outside their homes and participate in morning cultural parades (Shobha Yatra) with traditional Nauvari sarees, saffron turbans (pheta), and Enfield rallies.', 'Marks the victory of King Shalivahana and the beginning of the vibrant harvest season.'),
('banganga-festival', 'Banganga Music Festival', 'बाणगंगा संगीत महोत्सव', 'Dates vary by edition; confirm with the current organiser announcement', 'Banganga Water Tank, Walkeshwar, Mumbai', 'https://images.unsplash.com/photo-1514565131-fce0801e5785?auto=format&fit=crop&w=800&q=80', 'A magical open-air classical music festival held on the ancient stone steps of the sacred 12th-century Banganga Tank, accompanied by soft oil lamps (diyas) floating on the water.', 'Revitalizes Mumbai''s oldest living heritage precinct through sublime Hindustani classical ragas.'),
('dahi-handi', 'Dahi Handi', 'दहीहंडी', 'August – September (Janmashtami)', 'Mumbai, Thane, Pune and other cities', 'https://images.unsplash.com/photo-1598387993441-a364f854c3e1?auto=format&fit=crop&w=800&q=80', 'Teams known as Govindas form human pyramids to reach and break a suspended pot of curd, celebrating the playful stories of Lord Krishna. The event is known for teamwork, music and lively neighbourhood gatherings.', 'The festival celebrates devotion to Krishna while highlighting coordination, perseverance and community spirit.'),
('marbat-utsav', 'Marbat Utsav', 'मारबत उत्सव', 'August – September (second day of Pola)', 'Nagpur, especially Itwari', 'https://images.unsplash.com/photo-1576487248805-cf45f6bcc67f?auto=format&fit=crop&w=800&q=80', 'A distinctive Nagpur street festival in which large symbolic effigies are carried through the city in processions. The tradition combines community participation with social commentary and the symbolic removal of negativity.', 'Marbat Utsav expresses public concerns through symbolic effigies and celebrates Nagpur''s distinctive local tradition.'),
('jyotiba-jatra', 'Jyotiba Jatra', 'ज्योतिबा यात्रा', 'March – April (Chaitra Purnima)', 'Jyotiba Temple, Wadi Ratnagiri, Kolhapur', 'https://images.unsplash.com/photo-1561361513-2d000a50f0dc?auto=format&fit=crop&w=800&q=80', 'A major pilgrimage gathering at the hilltop Jyotiba Temple near Kolhapur. Devotees take part in processions, worship and the distinctive tradition of applying and tossing pink gulal.', 'The Jatra honours Jyotiba and brings devotees together in a shared expression of faith and regional tradition.'),
('shimga-holi', 'Kokanatil Shimga (Holi)', 'कोकणातील शिमगा', 'February – March (Phalguna)', 'Konkan region, including Ratnagiri, Sindhudurg and Raigad', 'https://images.unsplash.com/photo-1608889825205-eebdb9fc5806?auto=format&fit=crop&w=800&q=80', 'The Konkan form of Holi, known as Shimga, combines Holika bonfires with village processions, palkhi traditions, folk songs and dances. Rang Panchami colour celebrations follow in many communities.', 'Shimga welcomes the seasonal transition and brings village communities together through local ritual and folk culture.'),
('gauri-aagman', 'Gauri Aagman', 'गौरी आगमन', 'August – September (during Ganesh Chaturthi)', 'Mumbai, Pune, Nashik and communities across Maharashtra', 'https://images.unsplash.com/photo-1598387993441-a364f854c3e1?auto=format&fit=crop&w=800&q=80', 'Families welcome Goddess Gauri, associated with Parvati, during the Ganesh festival. Homes and community spaces are decorated, special worship is performed and the idols are later taken for immersion.', 'Gauri Aagman celebrates the goddess''s arrival and is associated with prosperity, family well-being and community bonds.'),
('khandoba-jatra', 'Khandoba Jatra', 'खंडोबा यात्रा', 'Somvati Amavasya (dates vary by lunar calendar)', 'Khandoba Temple, Jejuri, Pune district', 'https://images.unsplash.com/photo-1576487248805-cf45f6bcc67f?auto=format&fit=crop&w=800&q=80', 'Devotees visit Jejuri''s hilltop Khandoba Temple for worship and processions. Turmeric, known locally as bhandara, is central to the celebration and gives the temple precinct its golden appearance.', 'The Jatra honours Khandoba and reflects the devotion of farming and warrior communities, with prayers for protection and well-being.'),
('bail-pola', 'Bail Pola', 'बैलपोळा', 'August – September (Shravan Amavasya)', 'Rural Maharashtra, especially farming communities', 'https://images.unsplash.com/photo-1608889825205-eebdb9fc5806?auto=format&fit=crop&w=800&q=80', 'Farmers honour the bullocks that help cultivate their fields. Cattle are bathed, decorated with colourful ornaments and bells, rested from work and taken in ceremonial processions.', 'Bail Pola recognises the contribution of working cattle to agriculture and the livelihood of farming families.'),
('diwali', 'Diwali (Deepavali)', 'दिवाळी', 'October – November (five-day festival)', 'Across Maharashtra', 'https://images.unsplash.com/photo-1608889825205-eebdb9fc5806?auto=format&fit=crop&w=800&q=80', 'The five-day festival of lights brings families together for lamps, worship, festive food and visits. In Maharashtra, the days include Dhanatrayodashi, Narak Chaturdashi, Lakshmi Pujan, Padwa and Bhaubeej.', 'Diwali symbolises the triumph of light over darkness and good over evil, while strengthening family and community bonds.'),
('maharashtra-day', 'Maharashtra Day', 'महाराष्ट्र दिन', '1 May', 'Across Maharashtra; major state ceremony in Mumbai', 'https://images.unsplash.com/photo-1576487248805-cf45f6bcc67f?auto=format&fit=crop&w=800&q=80', 'Maharashtra Day marks the formation of the state on 1 May 1960. Flag-hoisting, official ceremonies, cultural programmes and public events commemorate the state''s history and the Samyukta Maharashtra movement.', 'The day honours the formation of Maharashtra and the people whose efforts helped establish a Marathi-speaking state.')
) as v(slug,name,marathi_name,dates,location,image,description,significance)
on conflict (slug) do nothing;

